<template>
  <main class="conversation-page" data-testid="conversation-page">
    <aside class="history-column" :class="{ open: historyOpen }" aria-label="会话历史"><header><div><p>与知识对话</p><h1>聊天记录</h1></div><button class="ui-icon" aria-label="新建聊天" @click="newConversation"><i class="i-lucide-square-pen" /></button></header><label class="history-search"><i class="i-lucide-search" /><input v-model="search" aria-label="搜索聊天记录" placeholder="搜索聊天记录" /></label><div class="history-list"><p v-if="store.listError" class="ui-error">{{ store.listError }}<button class="ui-button" @click="store.loadSessions">重试</button></p><p v-else-if="!filtered.length" class="empty-history">{{ search ? '没有匹配的聊天' : '开始一次对话，记录会保存在这里。' }}</p><template v-for="group in groups" :key="group.label"><p v-if="group.items.length" class="date-label">{{ group.label }}</p><div v-for="session in group.items" :key="session.id" class="history-item" :class="{ selected: session.id === store.sessionId }"><button class="session-link" @click="select(session.id)"><i class="i-lucide-message-circle" /><span>{{ session.title }}</span></button><button class="ui-icon session-edit" :aria-label="`管理会话 ${session.title}`" @click="editSession = session; editTitle = session.title; actionError = ''"><i class="i-lucide-ellipsis" /></button></div></template></div><footer><i class="i-lucide-lock-keyhole" />聊天记录仅自己可见</footer></aside>
    <section class="conversation-column"><header class="chat-header"><button class="ui-icon history-toggle" aria-label="切换聊天记录" @click="historyOpen = !historyOpen"><i class="i-lucide-panel-left-open" /></button><div><h2>{{ currentTitle }}</h2><span><i class="status-dot" />{{ store.running ? '正在生成回答' : '知识库问答' }}</span></div><button class="ui-icon" aria-label="收起为浮窗" @click="float"><i class="i-lucide-minimize-2" /></button></header><ConversationMessages /></section>
    <div v-if="editSession" class="dialog-overlay" @click.self="editSession = null"><form class="session-dialog" role="dialog" aria-modal="true" aria-label="管理会话" @submit.prevent="rename"><h2>管理会话</h2><label>会话名称<input v-model.trim="editTitle" class="ui-input" maxlength="300" required /></label><p v-if="actionError" class="ui-error">{{ actionError }}</p><footer><button type="button" class="ui-button danger" :disabled="saving" @click="remove">删除会话</button><span /><button type="button" class="ui-button" @click="editSession = null">取消</button><button class="ui-button primary" :disabled="saving || !editTitle">保存</button></footer></form></div>
  </main>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'; import { useRoute, useRouter } from 'vue-router';
import { useConversationStore, type Session } from './conversationStore'; import ConversationMessages from './ConversationMessages.vue'; import { errorMessage } from '../wiki/api';
const route = useRoute(); const router = useRouter(); const store = useConversationStore(); const search = ref(''); const historyOpen = ref(false);
const filtered = computed(() => store.sessions.filter(s => s.title.toLowerCase().includes(search.value.toLowerCase())));
const groups = computed(() => { const today = new Date(); today.setHours(0,0,0,0); const week = today.getTime() - 6 * 86400000; return [{ label: '今天', items: filtered.value.filter(s => new Date(s.updatedAt || s.createdAt || 0).getTime() >= +today) }, { label: '最近 7 天', items: filtered.value.filter(s => { const t = +new Date(s.updatedAt || s.createdAt || 0); return t < +today && t >= week; }) }, { label: '更早', items: filtered.value.filter(s => +new Date(s.updatedAt || s.createdAt || 0) < week) }]; });
const currentTitle = computed(() => store.sessions.find(s => s.id === store.sessionId)?.title || '新聊天');
onMounted(() => { store.floatingOpen = false; void store.boot(String(route.params.sessionId || '') || undefined); });
watch(() => route.params.sessionId, id => { if (id && id !== store.sessionId) void store.select(String(id)); });
watch(() => store.sessionId, id => { if (id && !route.params.sessionId) void router.replace({ name: 'conversations', params: { sessionId: id } }); });
async function newConversation() { await store.newConversation(); await router.push('/conversations'); }
async function select(id: string) { historyOpen.value = false; await router.push({ name: 'conversations', params: { sessionId: id } }); }
async function float() { await router.push('/knowledge-bases'); store.restore(); }
const editSession = ref<Session | null>(null); const editTitle = ref(''); const saving = ref(false); const actionError = ref('');
async function rename() { if (!editSession.value) return; saving.value = true; try { await store.rename(editSession.value, editTitle.value); editSession.value = null; } catch(e) { actionError.value = errorMessage(e); } finally { saving.value = false; } }
async function remove() { if (!editSession.value) return; saving.value = true; const id = editSession.value.id; try { await store.remove(id); editSession.value = null; if (route.params.sessionId === id) await router.replace('/conversations'); } catch(e) { actionError.value = errorMessage(e); } finally { saving.value = false; } }
</script>
<style scoped>
.conversation-page{display:grid;grid-template-columns:272px minmax(0,1fr);height:100%;min-height:0}.history-column{display:flex;flex-direction:column;min-height:0;border-right:1px solid #e8eee9;background:#fcfdfc;padding:26px 16px 16px}.history-column>header{display:flex;align-items:center;justify-content:space-between;padding:0 6px;margin-bottom:24px}.history-column header p{font-size:11px;color:#98a397;margin:0 0 7px}.history-column h1{font-size:20px;font-weight:600;margin:0;color:#3c5042}.history-search{display:flex;align-items:center;gap:8px;padding:10px 12px;border:1px solid #e3eae4;border-radius:8px;background:white;color:#9aa79d}.history-search input{min-width:0;width:100%;border:0;outline:0;font-size:12px;background:transparent}.history-search input::placeholder{color:#a3aea6}.history-list{min-height:0;flex:1;overflow:auto;padding-top:15px}.date-label{font-size:10px;color:#a0aba2;letter-spacing:.5px;margin:18px 10px 9px}.history-item{display:flex;align-items:center;border-radius:8px;margin-bottom:3px}.history-item:hover,.history-item.selected{background:#edf3ee}.session-link{min-width:0;flex:1;display:flex;align-items:center;gap:9px;border:0;background:none;padding:12px 10px;text-align:left;color:#6d7e70;font-size:12px;cursor:pointer}.session-link span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.history-item.selected .session-link{color:#34764c;font-weight:550}.session-edit{width:24px;height:28px;margin-right:5px;opacity:0}.history-item:hover .session-edit,.history-item.selected .session-edit,.session-edit:focus-visible{opacity:1}.empty-history{font-size:12px;color:#98a599;line-height:1.8;padding:18px 10px}.history-column>footer{font-size:10px;display:flex;gap:6px;align-items:center;color:#a1ada4;padding:14px 6px 0;border-top:1px solid #edf1ee}.conversation-column{min-width:0;min-height:0;display:flex;flex-direction:column}.chat-header{display:flex;align-items:center;gap:10px;justify-content:space-between;padding:20px 32px;border-bottom:1px solid #eef2ee;min-height:82px}.chat-header h2{font-size:14px;font-weight:550;margin:0 0 6px;color:#516656;max-width:500px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.chat-header span{display:flex;align-items:center;gap:5px;font-size:10px;color:#92a093}.status-dot{width:5px;height:5px;background:#75a582;border-radius:50%;display:inline-block}.history-toggle{display:none}.dialog-overlay{position:fixed;inset:0;z-index:100;display:grid;place-items:center;background:#19332244;padding:20px}.session-dialog{background:white;border-radius:16px;padding:28px;width:min(460px,100%);box-shadow:0 20px 80px #1a332622}.session-dialog h2{font-size:19px;margin-top:0}.session-dialog label{display:grid;gap:10px;color:#6a7e70;font-size:13px}.session-dialog footer{display:flex;gap:8px;margin-top:26px}.session-dialog footer span{flex:1}@media(max-width:1100px){.conversation-page{grid-template-columns:230px minmax(0,1fr)}}@media(max-width:900px){.conversation-page{grid-template-columns:minmax(0,1fr)}.history-column{display:none}.history-column.open{display:flex;position:absolute;inset:0 auto 0 0;width:260px;z-index:25;box-shadow:10px 0 30px #264e3022}.history-toggle{display:inline-grid}.chat-header{padding:16px 20px}.chat-header>div{flex:1;min-width:0}.chat-header h2{max-width:65vw}}
</style>
